"""Capture executed STRUCT UNION results independently with Spark 4.2.0."""

import argparse
import hashlib
import json
import os
from pathlib import Path
import sys
from zipfile import ZipFile


PAIRS = {
    "explicit_left": ("named_struct('x', 1) AS r", "named_struct('y', 2)"),
    "explicit_right": ("named_struct('x', 1)", "named_struct('y', 2) AS r"),
    "both_generated": ("named_struct('x', 1)", "named_struct('y', 2)"),
    "both_explicit": ("named_struct('x', 1) AS r", "named_struct('y', 2) AS r"),
    "positional_fields": ("named_struct('x', 1, 'y', 'left') AS r",
                          "named_struct('y', 2, 'x', 'right')"),
    "null_child": ("named_struct('x', CAST(NULL AS INT)) AS r", "named_struct('y', 2)"),
    "null_struct": ("CAST(NULL AS STRUCT<x: INT>) AS r", "named_struct('y', 2)"),
    "widened_child": ("named_struct('x', 1) AS r", "named_struct('x', 2L)"),
    "nested": ("named_struct('x', named_struct('a', 1)) AS r",
               "named_struct('y', named_struct('b', 2))"),
    "array_child": ("named_struct('x', array(named_struct('a', 1))) AS r",
                    "named_struct('y', array(named_struct('b', 2)))"),
    "scalar_expression": ("abs(v) AS r FROM VALUES (-1) t(v)", "abs(v) FROM VALUES (-2) t(v)"),
    "duplicate": ("named_struct('x', 1) AS r", "named_struct('y', 1)"),
    "empty_left": ("named_struct('x', v) AS r FROM VALUES (1) t(v) WHERE false",
                   "named_struct('x', 2)"),
    "empty_right": ("named_struct('x', 1) AS r",
                    "named_struct('y', v) FROM VALUES (2) t(v) WHERE false"),
    "column_values": ("named_struct('x', v) AS r FROM VALUES (1), (NULL), (1) t(v)",
                      "named_struct('y', v) FROM VALUES (2), (NULL), (1) t(v)"),
}


def encode(value):
    if value is None:
        return None
    if isinstance(value, (tuple, list)):
        return [encode(v) for v in value]
    return str(value).lower() if isinstance(value, bool) else str(value)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    assert not args.output.exists()
    os.environ["PYSPARK_PYTHON"] = sys.executable
    import pyspark
    from pyspark.sql import SparkSession, types

    spark = (SparkSession.builder.master("local[1]").appName("dar-union-struct-planning")
             .config("spark.ui.enabled", "false").config("spark.sql.shuffle.partitions", "1")
             .config("spark.sql.session.timeZone", "UTC").getOrCreate())
    try:
        assert spark.version == "4.2.0"
        spark.sparkContext.setLogLevel("ERROR")
        extension = {"ARROW:extension:name": "dar.struct", "ARROW:extension:metadata": "{}"}
        sources = [
            ("left_meta", "x", {"owner": "left"}, 1),
            ("right_meta", "x", {"owner": "right"}, 2),
            ("same_left", "x", {"owner": "kept"}, 1),
            ("same_right", "x", {"owner": "kept"}, 2),
            ("empty_meta", "x", {}, 2),
            ("marked_left", "x", {"owner": "kept", "__autoGeneratedAlias": "true"}, 1),
            ("marked_right", "x", {"owner": "kept", "__autoGeneratedAlias": "true"}, 2),
            ("renamed_meta", "y", {"owner": "right"}, 2),
            ("renamed_same", "y", {"owner": "kept"}, 2),
            ("renamed_empty", "y", {}, 2),
            ("extension_left", "x", {"owner": "left", **extension}, 1),
            ("extension_right", "x", {"owner": "right", **extension}, 2),
        ]
        inputs = []
        for name, child, metadata, value in sources:
            schema = types.StructType([types.StructField("r", types.StructType([
                types.StructField(child, types.IntegerType(), False)]), False, metadata)])
            rows = [((value,),)]
            spark.createDataFrame(rows, schema).createOrReplaceTempView(name)
            inputs.append({"name": name, "schema": json.loads(schema.json()),
                           "rows": [encode(row) for row in rows]})
        jar, = (Path(pyspark.__file__).parent / "jars").glob("spark-common-utils_*.jar")
        with ZipFile(jar) as archive:
            build = archive.read("spark-version-info.properties").decode()
        records = [{"spark_version": spark.version, "spark_build": build, "inputs": inputs,
                    "capture_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}]
        queries = {}
        for op in ["UNION", "UNION ALL"]:
            suffix = op.lower().replace(" ", "_")
            queries.update({f"{name}_{suffix}": f"SELECT {left} {op} SELECT {right}"
                            for name, (left, right) in PAIRS.items()})
            union = f"SELECT named_struct('x', 1) AS r {op} SELECT named_struct('y', 2)"
            queries[f"three_inputs_{suffix}"] = f"{union} {op} SELECT named_struct('z', 3)"
            queries[f"outer_extract_{suffix}"] = f"SELECT r.x FROM ({union}) q WHERE r.x > 1"
            queries[f"outer_count_{suffix}"] = f"SELECT count(*) AS n FROM ({union}) q"
            generated = f"SELECT named_struct('x', 1) {op} SELECT named_struct('y', 2)"
            queries[f"three_generated_{suffix}"] = f"{generated} {op} SELECT named_struct('z', 3)"
            queries[f"generated_outer_extract_{suffix}"] = f"SELECT r.x FROM ({generated}) q(r) WHERE r.x > 1"
            queries[f"generated_count_star_{suffix}"] = f"SELECT count(*) AS n FROM ({generated}) q(r)"
            queries[f"generated_count_struct_{suffix}"] = f"SELECT count(r) AS n FROM ({generated}) q(r)"
            queries[f"generated_group_struct_{suffix}"] = f"SELECT count(*) AS n FROM ({generated}) q(r) GROUP BY r"
            queries[f"generated_group_extract_{suffix}"] = f"SELECT r.x AS x, count(*) AS n FROM ({generated}) q(r) GROUP BY r"
            source_union = lambda left, right: f"SELECT r FROM {left} {op} SELECT r FROM {right}"
            different = source_union("left_meta", "right_meta")
            queries[f"source_different_owner_group_{suffix}"] = f"SELECT count(*) AS n FROM ({different}) q GROUP BY r"
            queries[f"source_different_owner_count_{suffix}"] = f"SELECT count(*) AS n FROM ({different}) q"
            queries[f"source_different_owner_direct_{suffix}"] = different
            same = source_union("same_left", "same_right")
            queries[f"source_same_owner_group_{suffix}"] = f"SELECT count(*) AS n FROM ({same}) q GROUP BY r"
            for name, left, right in [
                ("different", "left_meta", "renamed_meta"),
                ("same", "same_left", "renamed_same"),
                ("right_only", "empty_meta", "renamed_meta"),
                ("left_only", "left_meta", "renamed_empty"),
            ]:
                renamed = source_union(left, right)
                queries[f"source_renamed_{name}_{suffix}"] = f"SELECT count(*) AS n FROM ({renamed}) q GROUP BY r"
            queries[f"source_extension_direct_{suffix}"] = source_union("extension_left", "extension_right")
        queries.update({
            "scalar_control": "SELECT 1 AS n",
            "explicit_right_group_struct": "SELECT count(*) AS n FROM (SELECT named_struct('x', 1) UNION ALL SELECT named_struct('y', 2) AS r) q(r) GROUP BY r",
            "nullable_generated_count_struct": "SELECT count(r) AS n FROM (SELECT CAST(NULL AS STRUCT<x:INT>) UNION ALL SELECT named_struct('x', 2)) q(r)",
            "generated_scalar_group": "SELECT count(*) AS n FROM (SELECT abs(v) FROM VALUES (-1),(-2) t(v) UNION ALL SELECT abs(v) FROM VALUES (-3) t(v)) q(r) GROUP BY r",
            "identical_generated_branches": "SELECT count(*) AS n FROM (SELECT named_struct('x',1) UNION SELECT named_struct('x',1)) q(r) GROUP BY r",
            "empty_generated_branch": "SELECT count(r) AS n FROM (SELECT named_struct('x',v) FROM VALUES(1) t(v) WHERE false UNION ALL SELECT named_struct('x',2)) q(r)",
            "empty_generated_group": "SELECT count(*) AS n FROM (SELECT named_struct('x',v) FROM VALUES(1) t(v) WHERE false UNION ALL SELECT named_struct('x',2)) q(r) GROUP BY r",
            "cte_generated_group": "WITH q AS (SELECT named_struct('x',1) AS r UNION ALL SELECT named_struct('y',2)) SELECT r, count(*) AS n FROM q GROUP BY r",
            "non_union_generated_group": "SELECT count(*) AS n FROM (SELECT abs(v) FROM VALUES(-1),(-2) t(v)) q(r) GROUP BY r",
        })
        queries.update({
            "source_scalar_control": "SELECT 1 AS n",
            "source_marked_same_owner_group": "SELECT count(*) AS n FROM (SELECT r FROM marked_left UNION SELECT r FROM marked_right) q GROUP BY r",
            "source_left_only_owner_group": "SELECT count(*) AS n FROM (SELECT r FROM left_meta UNION SELECT r FROM empty_meta) q GROUP BY r",
            "source_right_only_owner_group": "SELECT count(*) AS n FROM (SELECT r FROM empty_meta UNION SELECT r FROM right_meta) q GROUP BY r",
            "source_different_owner_group_extract": "SELECT r.x AS n FROM (SELECT r FROM left_meta UNION ALL SELECT r FROM right_meta) q GROUP BY r",
            "source_non_union_group": "SELECT count(*) AS n FROM left_meta GROUP BY r",
        })
        source = "FROM VALUES (1), (2), (3), (4) t(id)"
        queries["pruned_union_all"] = (f"SELECT id, s FROM (SELECT id, named_struct('v', id) AS s {source} "
                                       f"UNION ALL SELECT id, named_struct('v', id) {source}) q WHERE id >= 3")
        for ansi in [False, True]:
            spark.conf.set("spark.sql.ansi.enabled", str(ansi).lower())
            for name, sql in queries.items():
                frame = spark.sql(sql)
                rows = [encode(row) for row in frame.collect()]
                rows.sort(key=lambda row: json.dumps(row, separators=(",", ":")))
                records.append({"id": name, "sql": sql, "ansi": ansi, "rows": rows,
                                "schema": json.loads(frame._jdf.queryExecution().executedPlan().schema().json())})
        with args.output.open("x") as output:
            for record in records:
                output.write(json.dumps(record, separators=(",", ":")) + "\n")
        print(json.dumps({"observations": len(records) - 1}))
    finally:
        spark.stop()


if __name__ == "__main__":
    main()
